function filterBrowseTopics() {
  var subjFilter = $('qbSubj').value;
  var topicFilter = $('qbTopic').value;
  var html = '<option value="">All Topics</option>';
  var topicSet = new Set();
  BANK.forEach(function (q) {
    if (subjFilter && q.s !== subjFilter) return;
    topicSet.add(topicOf(q));
  });
  Array.from(topicSet).sort().forEach(function (t) {
    html += '<option value="' + t + '">' + t + '</option>';
  });
  $('qbTopic').innerHTML = html;
  if (topicFilter) $('qbTopic').value = topicFilter;
}

