/* ---------------- QBank + Test multi-select chips ---------------- */
var QB = { subjs: {}, topics: {} };
var T = { subjs: {} };
function renderQBChips() {
  var subjHtml = cmAllSubjects().map(function (s) {
    return '<span class="chip' + (QB.subjs[s] ? ' on' : '') + '" data-s="' + s + '">' + s + '</span>';
  }).join('');
  $('qbSubjList').innerHTML = subjHtml;
  var topicHtml = topicsFor(QB.subjs, $('qbSource').value).map(function (t) {
    return '<span class="chip' + (QB.topics[t] ? ' on' : '') + '" data-t="' + t + '">' + t + '</span>';
  }).join('');
  $('qbTopicList').innerHTML = topicHtml;
  $('qbSubjList').querySelectorAll('.chip').forEach(function (el) {
    el.addEventListener('click', function () {
      var s = el.dataset.s;
      if (QB.subjs[s]) delete QB.subjs[s]; else QB.subjs[s] = true;
      QB.topics = {};
      renderQBChips();
      renderTree();
    });
  });
  $('qbTopicList').querySelectorAll('.chip').forEach(function (el) {
    el.addEventListener('click', function () {
      var t = el.dataset.t;
      if (QB.topics[t]) delete QB.topics[t]; else QB.topics[t] = true;
      renderQBChips();
      renderTree();
    });
  });
}
function renderTChips() {
  $('tSubj').innerHTML = SUBJECTS.map(function (s) {
    return '<span class="chip' + (T.subjs[s] ? ' on' : '') + '" data-s="' + s + '">' + s + '</span>';
  }).join('');
  $('tSubj').querySelectorAll('.chip').forEach(function (el) {
    el.addEventListener('click', function () {
      var s = el.dataset.s;
      if (T.subjs[s]) delete T.subjs[s]; else T.subjs[s] = true;
      renderTChips();
    });
  });
}

